actions.action:
on_stav_label: f.on_stav_label, on_meno: f.on_meno, on_priezvisko: f.on_priezvisko,
on_ziadatel: f.on_ziadatel, on_ziadatel_meno: f.on_ziadatel_meno,
on_pozicia: f.on_pozicia, on_historia: f.on_historia, on_protokol: f.on_protokol,
on_systemy: f.on_systemy;

def ja = loggedUser()
// KLUC moznosti, nie popisok - popisok si engine prelozi sam.
change on_stav_label value { "navrh" }
change on_ziadatel value { [ja.id] }
change on_ziadatel_meno value { kto(ja) }
change on_historia value { "" }
change on_protokol value { "" }
// Vsetky tri ucty su default - odskrtnut sa da, ale bezny nastup ich chce.
change on_systemy value { ["entra", "atlassian", "netgrif"] }
changeCaseProperty("title").about { nazov(on_priezvisko, on_meno, on_pozicia) }
changeCaseProperty("color").about { "grey" }

document.function:
{ def u ->
    // `?.` chráni pred null, nie pred chýbajúcou property.
    return (u.hasProperty("fullName") && u.fullName) ? (u.fullName as String) : (u.email as String)
}

{ def on_priezvisko, def on_meno, def on_pozicia ->
    // BEZ STAVU: `Case.title` je v engine obycajny `String`, takze sa
    // neprekladá - slovensky stav v nazve by bol v anglickom portali jedina
    // slovenska vec v kazdom zozname. Stav nesie pole `on_stav_label`
    // a stlpec. Podrobne RUNBOOK 9.
    def p = ((on_priezvisko.value ?: "") as String).trim()
    def m = ((on_meno.value ?: "") as String).trim()
    def poz = ((on_pozicia.value ?: "") as String).trim()
    def clovek = ([p, m].findAll { it }).join(" ")
    if (!clovek) return ((useCase.visualId ?: "?") as String)
    return poz ? (clovek + " – " + poz) : clovek
}

{ def on_historia, def riadok ->
    def stare = ((on_historia.value ?: "") as String)
    def novy = java.time.LocalDateTime.now().withNano(0).toString() + "  " + (riadok as String)
    def vsetky = ([novy] + (stare ? stare.split("\n") as List : []))
    // Strop, aby pole nerastlo donekonecna - stare riadky su v audite enginu.
    if (vsetky.size() > 60) vsetky = vsetky[0..59]
    change on_historia value { vsetky.join("\n") }
}

{ def pole ->
    // `multichoice_map` vracia raz Collection, raz obal s `.value`, raz String.
    def raw = pole.value
    if (raw == null) return []
    if (raw instanceof Collection) return raw.collect { it as String }
    if (raw.hasProperty("value") && raw.value instanceof Collection) {
        return raw.value.collect { it as String }
    }
    def s = (raw as String).trim()
    return s ? [s] : []
}

{ def text ->
    def s = ((text ?: "") as String)
    s = java.text.Normalizer.normalize(s, java.text.Normalizer.Form.NFD)
    s = s.replaceAll("\\p{InCombiningDiacriticalMarks}+", "")
    return s.toLowerCase().replaceAll("[^a-z0-9]+", "")
}

{ def hodnota ->
    def mail = ((hodnota ?: "") as String).trim()
    return mail ==~ /^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$/
}

{ def pole ->
    // Hodnota `userList` pola je UserListFieldValue s `userValues`, NIE zoznam
    // id - `.collect { it.id }` priamo na nej vyhodi
    // "No such property: id for class ... UserListFieldValue" uprostred akcie,
    // teda po tom, co uz cast zmien prebehla.
    //
    // A `u?._id` na jednotlivom UserFieldValue vyhodi to iste: `?.` chrani
    // pred null, nie pred chybajucou property.
    def raw = pole?.value
    if (raw == null) return []
    def users = raw.hasProperty("userValues") ? raw.userValues : (raw instanceof List ? raw : null)
    if (!users) return []
    return users.collect { u ->
        if (u == null) return null
        if (u instanceof String) return u
        if (u instanceof Map) return (u["_id"] ?: u["id"])
        return u.hasProperty("id") ? u.id : null
    }.findAll { it != null }.collect { it as String }
}

{ def ja ->
    // Kto smie tento nastup schvalit. `usersWithRoleAll` je primitivum delegata
    // ("kto vsetko ma rolu X"); `usersWithRole` filtruje ZADANY zoznam, co je
    // ina otazka.
    //
    // ZADAVATEL SA ZO ZOZNAMU VYHADZUJE. Styri oci tak nezacinaju odmietnutim,
    // ale tym, ze si clovek sam seba ani nevie vybrat. Guard vo `finish`
    // zostava ako druha linia - pole sa da prepisat cez API.
    def mojeId = (ja?.id ?: "") as String
    def out = [:]
    usersWithRoleAll("veduci", "onboarding/on_nastup").each { String id ->
        if (id == mojeId) return
        def u = null
        try { u = userService.findById(id, false) } catch (Exception e) { u = null }
        // Kluc moznosti je userId - hex ObjectId, takze v nom nie je `.` ani `$`
        // (Mongo to v nazvoch poli zakazuje, C17).
        out.put(id, u != null ? kto(u) : id)
    }
    return out
}

actions.action:
on_systemy: f.on_systemy, on_meno: f.on_meno, on_priezvisko: f.on_priezvisko,
on_firemny_email: f.on_firemny_email, on_heslo: f.on_heslo, on_profil: f.on_profil,
on_entra_skupiny: f.on_entra_skupiny, on_atlassian_tim: f.on_atlassian_tim,
on_protokol: f.on_protokol, on_ucet: f.on_ucet, on_historia: f.on_historia;

def mail = ((on_firemny_email.value ?: "") as String).trim()
if (!je_email(mail)) {
    throw new java.lang.IllegalStateException("Firemný e-mail nemá platný tvar: " + mail)
}
def systemy = ako_zoznam(on_systemy)
if (!systemy) {
    throw new java.lang.IllegalStateException("Nie je zaškrtnutý žiadny účet.")
}

def riadky = []
def znacka = (bez_diakritiky(on_priezvisko.value) + "-" +
        String.format("%04d", (new java.util.Random()).nextInt(10000)))

// ---------------------------------------------------------------------------
// SEM PRIDU SKUTOCNE KONEKTORY. Kazdy z nich je I/O na cudzie API, teda
// primitivum v `EtaskActionDelegate` (vrstva 2), volane odtialto menom -
// napr. `entraCreateUser(mail, meno, priezvisko, skupiny)`. V sieti zostane
// tento zoznam a jeho vysledok; HTTP klient, token a retry patria do delegatu.
// Dovtedy sa krok zapise do protokolu s fiktivnym identifikatorom, aby sa dal
// cely proces prejst a odprezentovat.
// ---------------------------------------------------------------------------
def skupiny = ((on_entra_skupiny.value ?: "") as String).trim()
def tim = ((on_atlassian_tim.value ?: "") as String).trim()
if (systemy.contains("entra")) {
    riadky << ("[SIMULACIA] Entra ID účet " + mail + (skupiny ? (", skupiny: " + skupiny) : "") +
            " -> objectId=ent-" + znacka)
}
if (systemy.contains("atlassian")) {
    riadky << ("[SIMULACIA] Atlassian účet " + mail + (tim ? (", tím: " + tim) : "") +
            " -> accountId=atl-" + znacka)
}

// Netgrif ucet vznika SKUTOCNE - `createNewUser` je primitivum delegatu.
// Toto je ta cast zadania, ktora ma po dobehnuti procesu realny vysledok:
// clovek sa vie prihlasit do tejto aplikacie.
if (systemy.contains("netgrif")) {
    if (((on_ucet.value ?: "") as String).trim()) {
        riadky << ("Netgrif účet už existuje: " + ((on_ucet.value ?: "") as String).trim())
    } else if (findUserByEmail(mail) != null) {
        change on_ucet value { mail }
        riadky << ("Netgrif účet už v inštancii bol: " + mail)
    } else if (!registrationService.isPasswordSufficient(formPassword(on_heslo.value))) {
        throw new java.lang.IllegalStateException("Počiatočné heslo nespĺňa požiadavky inštancie.")
    } else {
        def novy = createNewUser(((on_meno.value ?: "") as String).trim(),
                                 ((on_priezvisko.value ?: "") as String).trim(),
                                 mail, formPassword(on_heslo.value), ["ROLE_USER"])
        change on_ucet value { mail }
        riadky << ("Netgrif účet vytvorený: " + mail + " (ROLE_USER)")
        def profil = ((on_profil.value ?: "zamestnanec") as String)
        if (profil && profil != "zamestnanec") {
            if (setProcessRole(novy.stringId as String, profil, "onboarding/on_nastup", "vsetky", true)) {
                riadky << ("procesná rola: " + profil)
            } else {
                riadky << ("NEPODARILO SA prideliť procesnú rolu " + profil)
            }
        }
        // Heslo sa z pripadu maze hned po vytvoreni uctu.
        change on_heslo value { "" }
    }
}

def stare = ((on_protokol.value ?: "") as String)
change on_protokol value { (riadky.join("\n") + (stare ? ("\n" + stare) : "")) }
do_historie(on_historia, "účty vytvoril " + kto(loggedUser()) + " (" + riadky.size() + " položiek)")

on_schvalovatel_vyber: f.on_schvalovatel_vyber;

// Pri KAZDOM otvoreni znova. `change ... options { }` v `create` udalosti
// pripadu sa neuchova (B11), a zoznam veducich sa medzitym meni.
change on_schvalovatel_vyber options { nadriadeni(loggedUser()) }

on_meno: f.on_meno, on_priezvisko: f.on_priezvisko, on_systemy: f.on_systemy,
on_nastup_datum: f.on_nastup_datum, on_schvalovatel_vyber: f.on_schvalovatel_vyber;

// Sem validacie, ktore `required` neoveri. Odmietnutie vrati HTTP 200
// a dovod v tele ako `error` - test na stavovy kod ho prehliadne.
if (!((on_meno.value ?: "") as String).trim() || !((on_priezvisko.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException("Meno aj priezvisko musia byť vyplnené.")
}
if (!ako_zoznam(on_systemy)) {
    throw new java.lang.IllegalStateException("Vyber aspoň jeden účet, ktorý sa má vytvoriť.")
}
if (on_nastup_datum.value == null) {
    throw new java.lang.IllegalStateException("Dátum nástupu musí byť vyplnený.")
}
def vybrany = ((on_schvalovatel_vyber.value ?: "") as String).trim()
if (!vybrany) {
    throw new java.lang.IllegalStateException("Vyber vedúceho, ktorý má nástup schváliť.")
}
if (vybrany == ((loggedUser()?.id ?: "") as String)) {
    throw new java.lang.IllegalStateException("Vlastnú žiadosť si schváliť nemôžeš.")
}

on_meno: f.on_meno, on_priezvisko: f.on_priezvisko, on_pozicia: f.on_pozicia,
on_stav_label: f.on_stav_label, on_podane_o: f.on_podane_o, on_historia: f.on_historia,
on_firemny_email: f.on_firemny_email, on_schvalovatel_vyber: f.on_schvalovatel_vyber,
on_schvalovatelia: f.on_schvalovatelia, on_schvalovatel_meno: f.on_schvalovatel_meno,
on_komentar: f.on_komentar;

change on_stav_label value { "schvalenie" }
change on_podane_o value { java.time.LocalDateTime.now() }
// Navrh firemneho mailu, ked ho zadavatel nechal prazdny.
if (!((on_firemny_email.value ?: "") as String).trim()) {
    change on_firemny_email value {
        bez_diakritiky(on_meno.value) + "." + bez_diakritiky(on_priezvisko.value) + "@ditec.sk"
    }
}
// Vybrany clovek ide do `userList` - na nom visi `userRef` schvalovacieho
// prechodu. Bez tohto kroku by ulohu nemal kto prevziat.
def id = ((on_schvalovatel_vyber.value ?: "") as String).trim()
change on_schvalovatelia value { [id] }
def u = null
try { u = userService.findById(id, false) } catch (Exception e) { u = null }
change on_schvalovatel_meno value { u != null ? kto(u) : id }
// Komentar z predchadzajuceho kola sa vycisti - inak by pri druhom podani
// visel pri ziadosti stary dovod vratenia. V `on_historia` zostava.
change on_komentar value { "" }
do_historie(on_historia, "podal " + kto(loggedUser()) +
        ", schvaľuje " + (u != null ? kto(u) : id))
changeCaseProperty("title").about { nazov(on_priezvisko, on_meno, on_pozicia) }
changeCaseProperty("color").about { "blue" }

on_rozhodnutie: f.on_rozhodnutie, on_komentar: f.on_komentar, on_ziadatel: f.on_ziadatel,
go_vpred: f.go_vpred, go_spat: f.go_spat, go_zamietnute: f.go_zamietnute;

// Druha linia styroch oci: pole `on_schvalovatelia` sa da prepisat cez API,
// takze samotny vyber nestaci.
def moje = ((loggedUser()?.id ?: "") as String)
if (moje in id_z_userlistu(on_ziadatel)) {
    throw new java.lang.IllegalStateException("Vlastnú žiadosť si schváliť nemôžeš.")
}

// Routovacie priznaky patria do `phase="pre"`. V `post` sa token pohne
// s nulami a zmizne (reference C4).
def volba = ((on_rozhodnutie.value ?: "") as String)
if (!(volba in ["schvalit", "vratit", "zamietnut"])) {
    throw new java.lang.IllegalStateException(
            "Vyber, či nástup schvaľuješ, vraciaš na doplnenie alebo zamietaš.")
}
if (volba != "schvalit" && !((on_komentar.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException(
            "Vrátenie aj zamietnutie potrebuje komentár - inak zadávateľ nevie, čo opraviť.")
}
change go_vpred value { volba == "schvalit" ? 1 : 0 }
change go_spat value { volba == "vratit" ? 1 : 0 }
change go_zamietnute value { volba == "zamietnut" ? 1 : 0 }

on_rozhodnutie: f.on_rozhodnutie, on_komentar: f.on_komentar,
on_stav_label: f.on_stav_label, on_historia: f.on_historia, on_hotovo_o: f.on_hotovo_o;

def volba = ((on_rozhodnutie.value ?: "") as String)
change on_stav_label value {
    volba == "schvalit" ? "provisioning" : (volba == "vratit" ? "navrh" : "zamietnute")
}
changeCaseProperty("color").about { volba == "schvalit" ? "blue" : (volba == "vratit" ? "orange" : "red") }
if (volba == "zamietnut") {
    change on_hotovo_o value { java.time.LocalDateTime.now() }
}
def k = ((on_komentar.value ?: "") as String).trim()
do_historie(on_historia, "nadriadený: " + volba + " (" + kto(loggedUser()) + ")" +
        (k ? (" – " + k) : ""))

on_protokol: f.on_protokol, on_systemy: f.on_systemy, on_ucet: f.on_ucet;

if (!((on_protokol.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException(
            "Najprv stlač „Vytvoriť účty“ - protokol je prázdny.")
}
if (ako_zoznam(on_systemy).contains("netgrif") && !((on_ucet.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException("Účet v Netgrife ešte nevznikol.")
}

on_stav_label: f.on_stav_label, on_hotovo_o: f.on_hotovo_o, on_historia: f.on_historia,
on_heslo: f.on_heslo;

change on_stav_label value { "hotovo" }
change on_hotovo_o value { java.time.LocalDateTime.now() }
// Heslo v pripade nezostava ani ked ucet v Netgrife nevznikal.
change on_heslo value { "" }
do_historie(on_historia, "nástup ukončil " + kto(loggedUser()))
changeCaseProperty("color").about { "green" }
